		createAndOpenTrace();
		addThreads();
		traceManager.activateTrace(tb.trace);
		waitForTasks();

		waitForPass(() => assertThreadsPopulated());

		traceManager.activateTrace(null);
		waitForTasks();

		waitForPass(() => assertThreadsEmpty());
	}

