	/* @Test */
	public void testEditThreadComment()
    {
		createAndOpenTrace();
		addThreads();
		traceManager.activateTrace(tb.trace);
		waitForTasks();

		var tableModel = QueryPanelTestHelper.getTableModel(provider.panel);
		GhidraTable table = QueryPanelTestHelper.getTable(provider.panel);
		int commentModelIdx = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Comment", typeof(ValueProperty))
				.modelIndex();
		assertNotEquals(-1, commentModelIdx);

		runSwing(() => {
			tableModel.setValueAt(new("A different comment"), 0,
				commentModelIdx);
		});
		waitForTasks();

		waitForPass(() => assertEquals("A different comment",
			thread1.getObject().getAttribute(0, TraceThread.KEY_COMMENT).getValue()));
	}

