	public void testUndoRedoCausesUpdateInProvider()
    {
		createAndOpenTrace();
		addThreads();

		traceManager.activateTrace(tb.trace);
		waitForTasks();
		waitForPass(() => assertThreadsPopulated());

		undo(tb.trace);
		waitForTasks();
		waitForPass(() => assertThreadsEmpty());

		redo(tb.trace);
		waitForTasks();
		waitForPass(() => assertThreadsPopulated());
	}

